import React, { useRef, useEffect } from 'react';
import * as THREE from 'three';
import { FBXLoader, GLTFLoader } from 'three-stdlib';

const Model3D = ({ modelPath, containerStyle = {}, showBorder = true, enableRotation = false }) => {
  const mountRef = useRef(null);
  const sceneRef = useRef(null);
  const rendererRef = useRef(null);
  const animationIdRef = useRef(null);
  const mouseRef = useRef({ x: 0, y: 0, isDown: false });
  const modelRef = useRef(null);
  const mixerRef = useRef(null);
  const clockRef = useRef(new THREE.Clock());

  useEffect(() => {
    if (!mountRef.current) return;

    // Scene setup
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x111111);
    sceneRef.current = scene;

    // Camera setup - adjusted for better viewing
    const camera = new THREE.PerspectiveCamera(
      45, // Reduced FOV for better framing
      mountRef.current.clientWidth / mountRef.current.clientHeight,
      0.1,
      1000
    );

    // Neutral Lighting Setup (removing green tints)
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    // Main directional light - neutral white
    const mainDirectionalLight = new THREE.DirectionalLight(0xffffff, 1.0);
    mainDirectionalLight.position.set(0, 15, 0);
    mainDirectionalLight.castShadow = true;
    mainDirectionalLight.shadow.mapSize.width = 2048;
    mainDirectionalLight.shadow.mapSize.height = 2048;
    scene.add(mainDirectionalLight);

    // Side lights with neutral colors
    const frontLight = new THREE.DirectionalLight(0xffffff, 0.5);
    frontLight.position.set(0, 8, 15);
    scene.add(frontLight);

    const backLight = new THREE.DirectionalLight(0xffffff, 0.3);
    backLight.position.set(0, 8, -15);
    scene.add(backLight);

    const leftLight = new THREE.DirectionalLight(0xffffff, 0.4);
    leftLight.position.set(-15, 8, 0);
    scene.add(leftLight);

    const rightLight = new THREE.DirectionalLight(0xffffff, 0.4);
    rightLight.position.set(15, 8, 0);
    scene.add(rightLight);

    // Renderer setup
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(mountRef.current.clientWidth, mountRef.current.clientHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    rendererRef.current = renderer;

    const currentMount = mountRef.current;
    currentMount.appendChild(renderer.domElement);

    // Mouse event handlers for rotation
    const handleMouseDown = (event) => {
      mouseRef.current.isDown = true;
      mouseRef.current.x = event.clientX;
      mouseRef.current.y = event.clientY;
      currentMount.style.cursor = 'grabbing';
    };

    const handleMouseUp = () => {
      mouseRef.current.isDown = false;
      currentMount.style.cursor = 'grab';
    };

    const handleMouseMove = (event) => {
      if (!mouseRef.current.isDown || !modelRef.current) return;

      const deltaX = event.clientX - mouseRef.current.x;
      // Remove deltaY calculation as we don't need vertical rotation

      // Only allow horizontal rotation (Y-axis)
      modelRef.current.rotation.y += deltaX * 0.01;
      // Remove X-axis rotation to prevent top-bottom rotation

      mouseRef.current.x = event.clientX;
      mouseRef.current.y = event.clientY;
    };

    // Add mouse event listeners
    currentMount.addEventListener('mousedown', handleMouseDown);
    currentMount.addEventListener('mouseup', handleMouseUp);
    currentMount.addEventListener('mousemove', handleMouseMove);
    currentMount.addEventListener('mouseleave', handleMouseUp);
    currentMount.style.cursor = 'grab';

    // Determine loader based on file extension
    const isGLB = modelPath.toLowerCase().endsWith('.glb') || modelPath.toLowerCase().endsWith('.gltf');
    const loader = isGLB ? new GLTFLoader() : new FBXLoader();

    loader.load(
      modelPath,
      (result) => {
        const object = isGLB ? result.scene : result;
        modelRef.current = object;

        // Calculate bounding box for proper scaling and positioning
        const boundingBox = new THREE.Box3().setFromObject(object);
        const size = boundingBox.getSize(new THREE.Vector3());
        const center = boundingBox.getCenter(new THREE.Vector3());

        // Calculate scale to fit the model nicely in view
        const maxDimension = Math.max(size.x, size.y, size.z);
        let targetSize = 8; // Target size in scene units

        // Adjust target size based on file type
        if (isGLB) {
          targetSize = maxDimension > 10 ? 6 : 8;
        } else {
          targetSize = maxDimension > 100 ? 8 : 6;
        }

        const scale = targetSize / maxDimension;
        object.scale.setScalar(scale);

        // Center the model
        object.position.copy(center.multiplyScalar(-scale));

        // Position camera based on model size
        const distance = maxDimension * scale * 1.5;
        camera.position.set(distance * 0.8, distance * 0.6, distance * 1.2);
        camera.lookAt(0, 0, 0);

        // Setup animations for GLB files
        if (isGLB && result.animations && result.animations.length > 0) {
          mixerRef.current = new THREE.AnimationMixer(object);

          // Play all available animations
          result.animations.forEach((clip) => {
            const action = mixerRef.current.clipAction(clip);
            action.play();
          });
        }

        // Enable shadows and fix materials
        object.traverse((child) => {
          if (child.isMesh) {
            child.castShadow = true;
            child.receiveShadow = true;

            if (child.material) {
              const materials = Array.isArray(child.material) ? child.material : [child.material];

              materials.forEach((material) => {
                material.side = THREE.DoubleSide;

                if (!isGLB && material.map === null) {
                  const newMaterial = new THREE.MeshStandardMaterial({
                    color: material.color || 0x888888,
                    roughness: 0.7,
                    metalness: 0.1,
                    side: THREE.DoubleSide
                  });

                  if (Array.isArray(child.material)) {
                    const index = child.material.indexOf(material);
                    child.material[index] = newMaterial;
                  } else {
                    child.material = newMaterial;
                  }
                }

                if (material.map) {
                  material.map.colorSpace = THREE.SRGBColorSpace;
                  material.map.flipY = false;
                }
              });
            }
          }
        });

        scene.add(object);

        // Animation loop
        const animate = () => {
          animationIdRef.current = requestAnimationFrame(animate);

          const deltaTime = clockRef.current.getDelta();

          // Update animation mixer for GLB animations
          if (mixerRef.current) {
            mixerRef.current.update(deltaTime);
          }

          // Remove auto-rotation - only rotate if enableRotation is true
          if (enableRotation && modelRef.current) {
            modelRef.current.rotation.y += 0.005;
          }

          renderer.render(scene, camera);
        };
        animate();
      },
      (progress) => {
        console.log('Loading progress:', (progress.loaded / progress.total * 100) + '%');
      },
      (error) => {
        console.error('Error loading 3D model:', error);
        console.error('Model path:', modelPath);
        console.error('File type detected:', isGLB ? 'GLB/GLTF' : 'FBX');

        if (currentMount) {
          const errorDiv = document.createElement('div');
          errorDiv.style.cssText = `
            display: flex;
            align-items: center;
            justify-content: center;
            height: 100%;
            color: rgba(255, 255, 255, 0.7);
            text-align: center;
            font-family: Arial, sans-serif;
          `;
          errorDiv.innerHTML = `
            <div>
              <div style="font-size: 48px; margin-bottom: 16px;">🎭</div>
              <div>3D Model Loading...</div>
              <div style="font-size: 12px; margin-top: 8px; opacity: 0.5;">Please wait while we load the interactive experience</div>
            </div>
          `;
          currentMount.appendChild(errorDiv);
        }
      }
    );

    // Handle resize
    const handleResize = () => {
      if (!currentMount) return;

      camera.aspect = currentMount.clientWidth / currentMount.clientHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(currentMount.clientWidth, currentMount.clientHeight);
    };

    window.addEventListener('resize', handleResize);

    // Cleanup
    return () => {
      window.removeEventListener('resize', handleResize);

      if (currentMount) {
        currentMount.removeEventListener('mousedown', handleMouseDown);
        currentMount.removeEventListener('mouseup', handleMouseUp);
        currentMount.removeEventListener('mousemove', handleMouseMove);
        currentMount.removeEventListener('mouseleave', handleMouseUp);
      }

      if (animationIdRef.current) {
        cancelAnimationFrame(animationIdRef.current);
      }

      if (mixerRef.current) {
        mixerRef.current.stopAllAction();
        mixerRef.current = null;
      }

      if (currentMount && renderer.domElement) {
        currentMount.removeChild(renderer.domElement);
      }

      if (sceneRef.current) {
        sceneRef.current.clear();
      }

      if (rendererRef.current) {
        rendererRef.current.dispose();
      }
    };
  }, [modelPath, enableRotation]);

  return (
    <div
      ref={mountRef}
      style={{
        width: '100%',
        height: '400px',
        borderRadius: '0px',
        overflow: 'hidden',
        background: 'transparent',
        border: 'none',
        ...containerStyle
      }}
    />
  );
};

export default Model3D;

src/components/Navbar.js.content:
import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useBlog } from '../context/BlogContext';

const AdminToggle = () => {
  const { state, authenticateAdmin, logoutAdmin } = useBlog();
  const { isAdmin } = state;
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [password, setPassword] = useState('');
  const [errorMessage, setErrorMessage] = useState('');

  const handleAdminClick = () => {
    if (isAdmin) {
      logoutAdmin();
    } else {
      setShowPasswordModal(true);
      setPassword('');
      setErrorMessage('');
    }
  };

  const handlePasswordSubmit = (e) => {
    e.preventDefault();
    if (authenticateAdmin(password)) {
      setShowPasswordModal(false);
      setPassword('');
      setErrorMessage('');
    } else {
      setErrorMessage('Incorrect password. Please try again.');
      setPassword('');
    }
  };

  const handleModalClose = () => {
    setShowPasswordModal(false);
    setPassword('');
    setErrorMessage('');
  };

  return (
    <>
      <button
        onClick={handleAdminClick}
        style={{
          padding: '8px 12px',
          background: isAdmin ? 'var(--accent-green)' : 'transparent',
          color: isAdmin ? 'var(--primary-bg)' : 'var(--text-secondary)',
          border: `1px solid ${isAdmin ? 'var(--accent-green)' : 'var(--border-color)'}`,
          borderRadius: '8px',
          cursor: 'pointer',
          fontSize: '12px',
          transition: 'var(--transition-fast)',
          marginRight: '15px'
        }}
        title={isAdmin ? 'Logout Admin' : 'Admin Login'}
      >
        <i className={`fas ${isAdmin ? 'fa-user-shield' : 'fa-lock'}`} style={{ marginRight: '6px' }}></i>
        {isAdmin ? 'Admin' : 'Login'}
      </button>

      {/* Password Modal */}
      {showPasswordModal && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: 'rgba(0, 0, 0, 0.8)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          zIndex: 10000,
          backdropFilter: 'blur(10px)'
        }}>
          <div style={{
            background: 'var(--primary-bg)',
            border: '1px solid var(--border-color)',
            borderRadius: '16px',
            padding: '40px',
            width: '100%',
            maxWidth: '400px',
            boxShadow: '0 20px 40px rgba(0, 0, 0, 0.3)'
          }}>
            <div style={{ textAlign: 'center', marginBottom: '30px' }}>
              <i className="fas fa-shield-alt" style={{ 
                fontSize: '2rem', 
                color: 'var(--accent-green)', 
                marginBottom: '20px' 
              }}></i>
              <h3 style={{ 
                color: 'var(--text-primary)', 
                marginBottom: '10px',
                fontSize: '1.5rem'
              }}>
                Admin Access
              </h3>
              <p style={{ color: 'var(--text-secondary)', fontSize: '14px' }}>
                Enter the admin password to continue
              </p>
            </div>

            <form onSubmit={handlePasswordSubmit}>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="Enter admin password"
                autoFocus
                style={{
                  width: '100%',
                  padding: '12px 16px',
                  background: 'rgba(255, 255, 255, 0.05)',
                  border: `1px solid ${errorMessage ? '#ff3b30' : 'var(--border-color)'}`,
                  borderRadius: '8px',
                  color: 'var(--text-primary)',
                  fontSize: '14px',
                  outline: 'none',
                  marginBottom: '10px',
                  transition: 'var(--transition-fast)'
                }}
                onFocus={(e) => e.target.style.borderColor = errorMessage ? '#ff3b30' : 'var(--accent-green)'}
                onBlur={(e) => e.target.style.borderColor = errorMessage ? '#ff3b30' : 'var(--border-color)'}
              />

              {errorMessage && (
                <p style={{ 
                  color: '#ff3b30', 
                  fontSize: '12px', 
                  marginBottom: '20px',
                  textAlign: 'center'
                }}>
                  <i className="fas fa-exclamation-triangle" style={{ marginRight: '6px' }}></i>
                  {errorMessage}
                </p>
              )}

              <div style={{ display: 'flex', gap: '15px' }}>
                <button
                  type="button"
                  onClick={handleModalClose}
                  style={{
                    flex: 1,
                    padding: '12px',
                    background: 'transparent',
                    color: 'var(--text-secondary)',
                    border: '1px solid var(--border-color)',
                    borderRadius: '8px',
                    cursor: 'pointer',
                    fontSize: '14px',
                    transition: 'var(--transition-fast)'
                  }}
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  style={{
                    flex: 1,
                    padding: '12px',
                    background: 'var(--accent-green)',
                    color: 'var(--primary-bg)',
                    border: 'none',
                    borderRadius: '8px',
                    cursor: 'pointer',
                    fontSize: '14px',
                    fontWeight: '500',
                    transition: 'var(--transition-fast)'
                  }}
                >
                  Login
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </>
  );
};

const Navbar = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const location = useLocation();

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  const closeMobileMenu = () => {
    setIsMobileMenuOpen(false);
  };

  return (
    <nav className={`navbar ${isScrolled ? 'scrolled' : ''}`}>
      <div className="nav-container">
        <Link to="/" className="nav-logo" onClick={closeMobileMenu}>
          <svg className="nav-logo-svg" width="32" height="32" viewBox="0 0 32 32" xmlns="http://www.w3.org/2000/svg">
            <circle cx="16" cy="16" r="15" stroke="var(--accent-green)" strokeWidth="1" fill="none"/>
            <text x="16" y="20" textAnchor="middle" fill="var(--accent-green)" fontSize="14" fontWeight="300">L</text>
          </svg>
          Luphonix
        </Link>

        <div className={`nav-menu ${isMobileMenuOpen ? 'active' : ''}`}>
          <Link
            to="/"
            className={`nav-link ${location.pathname === '/' ? 'active' : ''}`}
            onClick={closeMobileMenu}
          >
            Home
          </Link>
          <Link
            to="/services"
            className={`nav-link ${location.pathname === '/services' ? 'active' : ''}`}
            onClick={closeMobileMenu}
          >
            Services
          </Link>
          <Link
            to="/projects"
            className={`nav-link ${location.pathname === '/projects' ? 'active' : ''}`}
            onClick={closeMobileMenu}
          >
            Projects
          </Link>
          <Link
            to="/blog"
            className={`nav-link ${location.pathname.startsWith('/blog') ? 'active' : ''}`}
            onClick={closeMobileMenu}
          >
            Blog
          </Link>
          <Link
            to="/contact"
            className={`nav-link ${location.pathname === '/contact' ? 'active' : ''}`}
            onClick={closeMobileMenu}
          >
            Contact
          </Link>
        </div>

        <div
          className={`nav-toggle ${isMobileMenuOpen ? 'active' : ''}`}
          onClick={toggleMobileMenu}
        >
          <span></span>
          <span></span>
          <span></span>
        </div>

        <div className="nav-actions">
            <AdminToggle />
          </div>
      </div>
    </nav>
  );
};

export default Navbar;

src/components/ProtectedRoute.js.content:
import React from 'react';
import { Navigate } from 'react-router-dom';
import { useBlog } from '../context/BlogContext';

const ProtectedRoute = ({ children }) => {
  const { state } = useBlog();
  const { isAdmin } = state;

  if (!isAdmin) {
    return <Navigate to="/blog" replace />;
  }

  return children;
};

export default ProtectedRoute;

src/components/RollingGallery.css.content:
.gallery-container {
  position: relative;
  height: 500px;
  width: 100%;
  overflow: hidden;
}

.gallery-gradient {
  position: absolute;
  top: 0;
  height: 100%;
  width: 48px;
  z-index: 10;
}

.gallery-gradient-left {
  left: 0;
  background: linear-gradient(to left, rgba(0, 0, 0, 0) 0%, var(--primary-bg) 100%);
}

.gallery-gradient-right {
  right: 0;
  background: linear-gradient(to right, rgba(0, 0, 0, 0) 0%, var(--primary-bg) 100%);
}

.gallery-content {
  display: flex;
  height: 100%;
  align-items: center;
  justify-content: center;
  perspective: 1000px;
  transform-style: preserve-3d;
}

.gallery-track {
  display: flex;
  height: auto;
  min-height: 200px;
  justify-content: center;
  align-items: center;
  cursor: grab;
  transform-style: preserve-3d;
  width: 100%;
}

.gallery-item {
  position: absolute;
  display: flex;
  height: fit-content;
  align-items: center;
  justify-content: center;
  padding: 8%;
  backface-visibility: hidden;
  cursor: pointer;
}

.gallery-img {
  pointer-events: none;
  height: 120px;
  width: 300px;
  border-radius: 15px;
  border: 3px solid var(--accent-green);
  object-fit: cover;
  transition: 0.3s ease;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
}

.gallery-item:hover .gallery-img {
  transform: scale(1.05);
  transition: 0.3s ease;
  box-shadow: 0 15px 40px rgba(0, 212, 170, 0.3);
}

.gallery-item-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background: linear-gradient(transparent, rgba(0, 0, 0, 0.8));
  color: white;
  padding: 20px;
  text-align: center;
  opacity: 0;
  transition: opacity 0.3s ease;
  border-radius: 0 0 15px 15px;
}

.gallery-item:hover .gallery-item-overlay {
  opacity: 1;
}

.gallery-item-overlay h4 {
  margin: 0 0 5px 0;
  font-size: 14px;
  font-weight: 600;
}

.gallery-category {
  font-size: 12px;
  color: var(--accent-green);
  font-weight: 500;
}

/* Popup Modal Styles */
.gallery-popup-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.8);
  backdrop-filter: blur(10px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  animation: fadeIn 0.3s ease;
}

.gallery-popup {
  background: var(--card-bg);
  border-radius: 20px;
  max-width: 900px;
  width: 90%;
  max-height: 90vh;
  overflow-y: auto;
  position: relative;
  box-shadow: 0 25px 50px rgba(0, 0, 0, 0.5);
  border: 1px solid rgba(255, 255, 255, 0.1);
  animation: slideUp 0.3s ease;
}

.gallery-popup-close {
  position: absolute;
  top: 20px;
  right: 20px;
  background: rgba(255, 255, 255, 0.1);
  border: none;
  border-radius: 50%;
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  cursor: pointer;
  z-index: 10;
  transition: all 0.3s ease;
}

.gallery-popup-close:hover {
  background: rgba(255, 255, 255, 0.2);
  transform: scale(1.1);
}

.gallery-popup-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  min-height: 500px;
}

.gallery-popup-image {
  position: relative;
  overflow: hidden;
  border-radius: 20px 0 0 20px;
}

.gallery-popup-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s ease;
}

.gallery-popup-info {
  padding: 40px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.gallery-popup-header {
  margin-bottom: 20px;
}

.gallery-popup-header h2 {
  margin: 0 0 10px 0;
  color: var(--text-primary);
  font-size: 2rem;
  font-weight: 700;
}

.gallery-popup-category {
  background: var(--accent-green);
  color: white;
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.gallery-popup-description {
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 30px;
  font-size: 16px;
}

.gallery-popup-technologies {
  margin-bottom: 30px;
}

.gallery-popup-technologies h3 {
  margin: 0 0 15px 0;
  color: var(--text-primary);
  font-size: 1.2rem;
  font-weight: 600;
}

.tech-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.tech-tag {
  background: rgba(var(--accent-green-rgb), 0.1);
  color: var(--accent-green);
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 500;
  border: 1px solid rgba(var(--accent-green-rgb), 0.2);
}

.gallery-popup-actions {
  display: flex;
  gap: 15px;
}

.gallery-popup-btn {
  flex: 1;
  padding: 12px 20px;
  border: none;
  border-radius: 10px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
  display: flex;
  align-items: center;
  justify-content: center;
}

.gallery-popup-btn.primary {
  background: var(--accent-green);
  color: white;
}

.gallery-popup-btn.primary:hover {
  background: #00b894;
  transform: translateY(-2px);
}

.gallery-popup-btn.secondary {
  background: transparent;
  color: var(--accent-green);
  border: 2px solid var(--accent-green);
}

.gallery-popup-btn.secondary:hover {
  background: var(--accent-green);
  color: white;
  transform: translateY(-2px);
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes slideUp {
  from { 
    opacity: 0;
    transform: translateY(50px) scale(0.9);
  }
  to { 
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@media (max-width: 768px) {
  .gallery-item {
    padding: 6%;
  }
  .gallery-img {
    height: 100px;
    width: 220px;
  }

  .gallery-popup {
    width: 95%;
    max-height: 95vh;
  }

  .gallery-popup-content {
    grid-template-columns: 1fr;
  }

  .gallery-popup-image {
    border-radius: 20px 20px 0 0;
    max-height: 300px;
  }

  .gallery-popup-info {
    padding: 30px 20px;
  }

  .gallery-popup-header h2 {
    font-size: 1.5rem;
  }

  .gallery-popup-actions {
    flex-direction: column;
  }

  .gallery-popup-btn {
    width: 100%;
  }
}

