              <p style={{ color: 'var(--text-muted)' }}>
                {searchTerm ? 'Try adjusting your search terms' : 'Create your first blog post'}
              </p>
            </div>
          )}
        </div>
      </section>
    </div>
  );
};

export default BlogAdmin;

src/pages/BlogCreate.js.content:
import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useBlog } from '../context/BlogContext';

const BlogCreate = () => {
  const navigate = useNavigate();
  const { dispatch } = useBlog();
  const [formData, setFormData] = useState({
    title: '',
    excerpt: '',
    content: '',
    featured_image: '',
    tags: '',
    author: '',
    read_time: 5
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const generateSlug = (title) => {
    return title
      .toLowerCase()
      .replace(/[^\w\s-]/g, '')
      .replace(/\s+/g, '-')
      .replace(/-+/g, '-')
      .trim();
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      const newPost = {
        id: Date.now(),
        ...formData,
        slug: generateSlug(formData.title),
        tags: formData.tags.split(',').map(tag => tag.trim()).filter(tag => tag),
        author: formData.author || 'Luphonix Team',
        created_at: new Date().toISOString(),
        read_time: parseInt(formData.read_time) || 5,
        featured_image: formData.featured_image || 'https://images.unsplash.com/photo-1486312338219-ce68d2c6f44d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80'
      };

      dispatch({ type: 'ADD_POST', payload: newPost });
      navigate('/blog/admin');
    } catch (error) {
      console.error('Error creating post:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="create-post-page">
      <section className="section">
        <div className="container" style={{ maxWidth: '800px' }}>
          <div style={{ marginBottom: '40px' }}>
            <Link 
              to="/blog/admin" 
              style={{ 
                color: 'var(--accent-green)', 
                textDecoration: 'none',
                display: 'inline-flex',
                alignItems: 'center',
                marginBottom: '30px',
                fontSize: '14px'
              }}
            >
              <i className="fas fa-arrow-left" style={{ marginRight: '10px' }}></i>
              Back to Admin
            </Link>

            <h1 className="section-title" style={{ textAlign: 'left', marginBottom: '10px' }}>
              Create New Blog Post
            </h1>
            <p style={{ color: 'var(--text-secondary)' }}>
              Fill in the details below to create a new blog post
            </p>
          </div>

          <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '30px' }}>
            {/* Title */}
            <div>
              <label style={{ 
                display: 'block', 
                marginBottom: '8px', 
                color: 'var(--text-primary)',
                fontSize: '14px',
                fontWeight: '300'
              }}>
                Post Title *
              </label>
              <input
                type="text"
                name="title"
                value={formData.title}
                onChange={handleChange}
                required
                placeholder="Enter the blog post title"
                style={{
                  width: '100%',
                  padding: '16px 20px',
                  background: 'rgba(255, 255, 255, 0.05)',
                  border: '1px solid var(--border-color)',
                  borderRadius: '12px',
                  color: 'var(--text-primary)',
                  fontSize: '16px',
                  outline: 'none',
                  transition: 'var(--transition-fast)'
                }}
              />
            </div>

            {/* Excerpt */}
            <div>
              <label style={{ 
                display: 'block', 
                marginBottom: '8px', 
                color: 'var(--text-primary)',
                fontSize: '14px',
                fontWeight: '300'
              }}>
                Excerpt *
              </label>
              <textarea
                name="excerpt"
                value={formData.excerpt}
                onChange={handleChange}
                required
                placeholder="Brief description of the post"
                rows={3}
                style={{
                  width: '100%',
                  padding: '16px 20px',
                  background: 'rgba(255, 255, 255, 0.05)',
                  border: '1px solid var(--border-color)',
                  borderRadius: '12px',
                  color: 'var(--text-primary)',
                  fontSize: '16px',
                  outline: 'none',
                  resize: 'vertical',
                  minHeight: '80px',
                  transition: 'var(--transition-fast)'
                }}
              />
            </div>

            {/* Content */}
            <div>
              <label style={{ 
                display: 'block', 
                marginBottom: '8px', 
                color: 'var(--text-primary)',
                fontSize: '14px',
                fontWeight: '300'
              }}>
                Content *
              </label>
              <textarea
                name="content"
                value={formData.content}
                onChange={handleChange}
                required
                placeholder="Write your blog post content here..."
                rows={12}
                style={{
                  width: '100%',
                  padding: '20px',
                  background: 'rgba(255, 255, 255, 0.05)',
                  border: '1px solid var(--border-color)',
                  borderRadius: '12px',
                  color: 'var(--text-primary)',
                  fontSize: '16px',
                  outline: 'none',
                  resize: 'vertical',
                  minHeight: '300px',
                  lineHeight: '1.6',
                  transition: 'var(--transition-fast)'
                }}
              />
            </div>

            {/* Row for Featured Image and Author */}
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
              <div>
                <label style={{ 
                  display: 'block', 
                  marginBottom: '8px', 
                  color: 'var(--text-primary)',
                  fontSize: '14px',
                  fontWeight: '300'
                }}>
                  Featured Image URL
                </label>
                <input
                  type="url"
                  name="featured_image"
                  value={formData.featured_image}
                  onChange={handleChange}
                  placeholder="https://example.com/image.jpg"
                  style={{
                    width: '100%',
                    padding: '16px 20px',
                    background: 'rgba(255, 255, 255, 0.05)',
                    border: '1px solid var(--border-color)',
                    borderRadius: '12px',
                    color: 'var(--text-primary)',
                    fontSize: '16px',
                    outline: 'none',
                    transition: 'var(--transition-fast)'
                  }}
                />
              </div>

              <div>
                <label style={{ 
                  display: 'block', 
                  marginBottom: '8px', 
                  color: 'var(--text-primary)',
                  fontSize: '14px',
                  fontWeight: '300'
                }}>
                  Author
                </label>
                <input
                  type="text"
                  name="author"
                  value={formData.author}
                  onChange={handleChange}
                  placeholder="Author name (optional)"
                  style={{
                    width: '100%',
                    padding: '16px 20px',
                    background: 'rgba(255, 255, 255, 0.05)',
                    border: '1px solid var(--border-color)',
                    borderRadius: '12px',
                    color: 'var(--text-primary)',
                    fontSize: '16px',
                    outline: 'none',
                    transition: 'var(--transition-fast)'
                  }}
                />
              </div>
            </div>

            {/* Row for Tags and Read Time */}
            <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '20px' }}>
              <div>
                <label style={{ 
                  display: 'block', 
                  marginBottom: '8px', 
                  color: 'var(--text-primary)',
                  fontSize: '14px',
                  fontWeight: '300'
                }}>
                  Tags (comma-separated)
                </label>
                <input
                  type="text"
                  name="tags"
                  value={formData.tags}
                  onChange={handleChange}
                  placeholder="React, JavaScript, Web Development"
                  style={{
                    width: '100%',
                    padding: '16px 20px',
                    background: 'rgba(255, 255, 255, 0.05)',
                    border: '1px solid var(--border-color)',
                    borderRadius: '12px',
                    color: 'var(--text-primary)',
                    fontSize: '16px',
                    outline: 'none',
                    transition: 'var(--transition-fast)'
                  }}
                />
              </div>

              <div>
                <label style={{ 
                  display: 'block', 
                  marginBottom: '8px', 
                  color: 'var(--text-primary)',
                  fontSize: '14px',
                  fontWeight: '300'
                }}>
                  Read Time (minutes)
                </label>
                <input
                  type="number"
                  name="read_time"
                  value={formData.read_time}
                  onChange={handleChange}
                  min="1"
                  max="60"
                  style={{
                    width: '100%',
                    padding: '16px 20px',
                    background: 'rgba(255, 255, 255, 0.05)',
                    border: '1px solid var(--border-color)',
                    borderRadius: '12px',
                    color: 'var(--text-primary)',
                    fontSize: '16px',
                    outline: 'none',
                    transition: 'var(--transition-fast)'
                  }}
                />
              </div>
            </div>

            {/* Submit Button */}
            <div style={{ display: 'flex', gap: '15px', justifyContent: 'flex-end', paddingTop: '20px' }}>
              <Link 
                to="/blog/admin"
                style={{
                  padding: '16px 30px',
                  background: 'transparent',
                  color: 'var(--text-secondary)',
                  border: '1px solid var(--border-color)',
                  borderRadius: '12px',
                  textDecoration: 'none',
                  fontSize: '16px',
                  transition: 'var(--transition-fast)',
                  display: 'inline-flex',
                  alignItems: 'center'
                }}
              >
                Cancel
              </Link>
              <button
                type="submit"
                disabled={isSubmitting}
                className="cta-button"
                style={{
                  padding: '16px 30px',
                  fontSize: '16px',
                  opacity: isSubmitting ? 0.7 : 1,
                  cursor: isSubmitting ? 'not-allowed' : 'pointer'
                }}
              >
                {isSubmitting ? 'Creating...' : 'Create Post'}
                {!isSubmitting && <i className="fas fa-plus" style={{ marginLeft: '10px' }}></i>}
              </button>
            </div>
          </form>
        </div>
      </section>
    </div>
  );
};

export default BlogCreate;

src/pages/BlogEdit.js.content:
import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link, Navigate } from 'react-router-dom';
import { useBlog } from '../context/BlogContext';

const BlogEdit = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { state, dispatch } = useBlog();
  const { posts } = state;

  const post = posts.find(p => p.id === parseInt(id));
  const [formData, setFormData] = useState({
    title: '',
    excerpt: '',
    content: '',
    featured_image: '',
    tags: '',
    author: '',
    read_time: 5
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    if (post) {
      setFormData({
        title: post.title,
        excerpt: post.excerpt,
        content: post.content || '',
        featured_image: post.featured_image,
        tags: post.tags.join(', '),
        author: post.author || '',
        read_time: post.read_time
      });
    }
  }, [post]);

  if (!post) {
    return <Navigate to="/blog/admin" replace />;
  }

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const generateSlug = (title) => {
    return title
      .toLowerCase()
      .replace(/[^\w\s-]/g, '')
      .replace(/\s+/g, '-')
      .replace(/-+/g, '-')
      .trim();
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      const updatedPost = {
        ...post,
        ...formData,
        slug: generateSlug(formData.title),
        tags: formData.tags.split(',').map(tag => tag.trim()).filter(tag => tag),
        read_time: parseInt(formData.read_time) || 5,
        updated_at: new Date().toISOString()
      };

      dispatch({ type: 'UPDATE_POST', payload: updatedPost });
      navigate('/blog/admin');
    } catch (error) {
      console.error('Error updating post:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="edit-post-page">
      <section className="section">
        <div className="container" style={{ maxWidth: '800px' }}>
          <div style={{ marginBottom: '40px' }}>
            <Link 
              to="/blog/admin" 
              style={{ 
                color: 'var(--accent-green)', 
                textDecoration: 'none',
                display: 'inline-flex',
                alignItems: 'center',
                marginBottom: '30px',
                fontSize: '14px'
              }}
            >
              <i className="fas fa-arrow-left" style={{ marginRight: '10px' }}></i>
              Back to Admin
            </Link>

            <h1 className="section-title" style={{ textAlign: 'left', marginBottom: '10px' }}>
              Edit Blog Post
            </h1>
            <p style={{ color: 'var(--text-secondary)' }}>
              Update the details of your blog post
            </p>
          </div>

          <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '30px' }}>
            {/* Title */}
            <div>
              <label style={{ 
                display: 'block', 
                marginBottom: '8px', 
                color: 'var(--text-primary)',
                fontSize: '14px',
                fontWeight: '300'
              }}>
                Post Title *
              </label>
              <input
                type="text"
                name="title"
                value={formData.title}
                onChange={handleChange}
                required
                placeholder="Enter the blog post title"
                style={{
                  width: '100%',
                  padding: '16px 20px',
                  background: 'rgba(255, 255, 255, 0.05)',
                  border: '1px solid var(--border-color)',
                  borderRadius: '12px',
                  color: 'var(--text-primary)',
                  fontSize: '16px',
                  outline: 'none',
                  transition: 'var(--transition-fast)'
                }}
              />
            </div>

            {/* Excerpt */}
            <div>
              <label style={{ 
                display: 'block', 
                marginBottom: '8px', 
                color: 'var(--text-primary)',
                fontSize: '14px',
                fontWeight: '300'
              }}>
                Excerpt *
              </label>
              <textarea
                name="excerpt"
                value={formData.excerpt}
                onChange={handleChange}
                required
                placeholder="Brief description of the post"
                rows={3}
                style={{
                  width: '100%',
                  padding: '16px 20px',
                  background: 'rgba(255, 255, 255, 0.05)',
                  border: '1px solid var(--border-color)',
                  borderRadius: '12px',
                  color: 'var(--text-primary)',
                  fontSize: '16px',
                  outline: 'none',
                  resize: 'vertical',
                  minHeight: '80px',
                  transition: 'var(--transition-fast)'
                }}
              />
            </div>

            {/* Content */}
            <div>
              <label style={{ 
                display: 'block', 
                marginBottom: '8px', 
                color: 'var(--text-primary)',
                fontSize: '14px',
                fontWeight: '300'
              }}>
                Content *
              </label>
              <textarea
                name="content"
                value={formData.content}
                onChange={handleChange}
                required
                placeholder="Write your blog post content here..."
                rows={12}
                style={{
                  width: '100%',
                  padding: '20px',
                  background: 'rgba(255, 255, 255, 0.05)',
                  border: '1px solid var(--border-color)',
                  borderRadius: '12px',
                  color: 'var(--text-primary)',
                  fontSize: '16px',
                  outline: 'none',
                  resize: 'vertical',
                  minHeight: '300px',
                  lineHeight: '1.6',
                  transition: 'var(--transition-fast)'
                }}
              />
            </div>

            {/* Row for Featured Image and Author */}
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
              <div>
                <label style={{ 
                  display: 'block', 
                  marginBottom: '8px', 
                  color: 'var(--text-primary)',
                  fontSize: '14px',
                  fontWeight: '300'
                }}>
                  Featured Image URL
                </label>
                <input
                  type="url"
                  name="featured_image"
                  value={formData.featured_image}
                  onChange={handleChange}
                  placeholder="https://example.com/image.jpg"
                  style={{
                    width: '100%',
                    padding: '16px 20px',
                    background: 'rgba(255, 255, 255, 0.05)',
                    border: '1px solid var(--border-color)',
                    borderRadius: '12px',
                    color: 'var(--text-primary)',
                    fontSize: '16px',
                    outline: 'none',
                    transition: 'var(--transition-fast)'
                  }}
                />
              </div>

              <div>
                <label style={{ 
                  display: 'block', 
                  marginBottom: '8px', 
                  color: 'var(--text-primary)',
                  fontSize: '14px',
                  fontWeight: '300'
                }}>
                  Author
                </label>
                <input
                  type="text"
                  name="author"
                  value={formData.author}
                  onChange={handleChange}
                  placeholder="Author name"
                  style={{
                    width: '100%',
                    padding: '16px 20px',
                    background: 'rgba(255, 255, 255, 0.05)',
                    border: '1px solid var(--border-color)',
                    borderRadius: '12px',
                    color: 'var(--text-primary)',
                    fontSize: '16px',
                    outline: 'none',
                    transition: 'var(--transition-fast)'
                  }}
                />
              </div>
            </div>

            {/* Row for Tags and Read Time */}
            <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '20px' }}>
              <div>
                <label style={{ 
                  display: 'block', 
                  marginBottom: '8px', 
                  color: 'var(--text-primary)',
                  fontSize: '14px',
                  fontWeight: '300'
                }}>
                  Tags (comma-separated)
                </label>
                <input
                  type="text"
                  name="tags"
                  value={formData.tags}
                  onChange={handleChange}
                  placeholder="React, JavaScript, Web Development"
                  style={{
                    width: '100%',
                    padding: '16px 20px',
                    background: 'rgba(255, 255, 255, 0.05)',
                    border: '1px solid var(--border-color)',
                    borderRadius: '12px',
                    color: 'var(--text-primary)',
                    fontSize: '16px',
                    outline: 'none',
                    transition: 'var(--transition-fast)'
                  }}
                />
              </div>

              <div>
                <label style={{ 
                  display: 'block', 
                  marginBottom: '8px', 
                  color: 'var(--text-primary)',
                  fontSize: '14px',
                  fontWeight: '300'
                }}>
                  Read Time (minutes)
                </label>
                <input
                  type="number"
                  name="read_time"
                  value={formData.read_time}
                  onChange={handleChange}
                  min="1"
                  max="60"
                  style={{
                    width: '100%',
                    padding: '16px 20px',
                    background: 'rgba(255, 255, 255, 0.05)',
                    border: '1px solid var(--border-color)',
                    borderRadius: '12px',
                    color: 'var(--text-primary)',
                    fontSize: '16px',
                    outline: 'none',
                    transition: 'var(--transition-fast)'
                  }}
                />
              </div>
            </div>

            {/* Submit Buttons */}
            <div style={{ display: 'flex', gap: '15px', justifyContent: 'flex-end', paddingTop: '20px' }}>
              <Link 
                to="/blog/admin"
                style={{
                  padding: '16px 30px',
                  background: 'transparent',
                  color: 'var(--text-secondary)',
                  border: '1px solid var(--border-color)',
                  borderRadius: '12px',
                  textDecoration: 'none',
                  fontSize: '16px',
                  transition: 'var(--transition-fast)',
                  display: 'inline-flex',
                  alignItems: 'center'
                }}
              >
                Cancel
              </Link>
              <button
                type="submit"
                disabled={isSubmitting}
                className="cta-button"
                style={{
                  padding: '16px 30px',
                  fontSize: '16px',
                  opacity: isSubmitting ? 0.7 : 1,
                  cursor: isSubmitting ? 'not-allowed' : 'pointer'
                }}
              >
                {isSubmitting ? 'Updating...' : 'Update Post'}
                {!isSubmitting && <i className="fas fa-save" style={{ marginLeft: '10px' }}></i>}
              </button>
            </div>
          </form>
        </div>
      </section>
    </div>
  );
};

export default BlogEdit;

src/pages/BlogPost.js.content:
import React, { useEffect } from 'react';
import { useParams, Link, Navigate } from 'react-router-dom';
import { useBlog } from '../context/BlogContext';

const BlogPost = () => {
  const { slug } = useParams();
  const { state } = useBlog();
  const { posts: blogPosts, isAdmin } = state;
  const post = blogPosts.find(p => p.slug === slug);

  useEffect(() => {
    // Add fade-in animation on scroll
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('animated');
        }
      });
    });

    document.querySelectorAll('.fade-in').forEach(el => observer.observe(el));

    return () => observer.disconnect();
  }, []);

  if (!post) {
    return <Navigate to="/blog" replace />;
  }

  const relatedPosts = blogPosts
    .filter(p => p.id !== post.id && p.tags.some(tag => post.tags.includes(tag)))
    .slice(0, 3);

  return (
    <div className="blog-post" style={{ paddingTop: '120px' }}>
      <div className="container" style={{ maxWidth: '900px' }}>
        <Link to="/blog" className="back-link" style={{
          display: 'inline-flex',
          alignItems: 'center',
          gap: '10px',
          color: 'var(--accent-green)',
          textDecoration: 'none',
          marginBottom: '40px',
          fontSize: '16px',
          fontWeight: '500',
          transition: 'all 0.3s ease'
        }}>
          <i className="fas fa-arrow-left"></i> Back to Blog
        </Link>

        <article className="blog-post-content">
          <header className="blog-post-header" style={{
            textAlign: 'center',
            marginBottom: '60px',
            paddingBottom: '40px',
            borderBottom: '1px solid rgba(255, 255, 255, 0.1)'
          }}>
            <div className="blog-post-meta" style={{
              display: 'flex',
              justifyContent: 'center',
              gap: '30px',
              marginBottom: '25px',
              fontSize: '14px',
              color: 'var(--text-secondary)',
              flexWrap: 'wrap'
            }}>
              <span style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <i className="fas fa-calendar" style={{ color: 'var(--accent-green)' }}></i>
                {new Date(post.created_at).toLocaleDateString()}
              </span>
              <span style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <i className="fas fa-clock" style={{ color: 'var(--accent-green)' }}></i>
                {post.read_time} min read
              </span>
              <span style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <i className="fas fa-user" style={{ color: 'var(--accent-green)' }}></i>
                {post.author || 'Luphonix Team'}
              </span>
            </div>

            <h1 className="blog-post-title" style={{
              fontSize: 'clamp(2rem, 5vw, 3.5rem)',
              fontWeight: '700',
              lineHeight: '1.2',
              marginBottom: '25px',
              background: 'linear-gradient(135deg, var(--text-primary), var(--accent-green))',
              backgroundClip: 'text',
              WebkitBackgroundClip: 'text',
              WebkitTextFillColor: 'transparent'
            }}>
              {post.title}
            </h1>

            <p className="blog-post-excerpt" style={{
              fontSize: '1.2rem',
              lineHeight: '1.6',
              color: 'var(--text-secondary)',
              maxWidth: '700px',
              margin: '0 auto 30px',
              fontWeight: '300'
            }}>
              {post.excerpt}
            </p>

            <div className="blog-post-tags" style={{
              display: 'flex',
              justifyContent: 'center',
              flexWrap: 'wrap',
              gap: '12px'
            }}>
              {post.tags.map(tag => (
                <span key={tag} className="tag" style={{
                  background: 'rgba(0, 212, 170, 0.1)',
                  color: 'var(--accent-green)',
                  padding: '8px 16px',
                  borderRadius: '25px',
                  fontSize: '12px',
                  fontWeight: '500',
                  border: '1px solid rgba(0, 212, 170, 0.3)',
                  transition: 'all 0.3s ease'
                }}>
                  {tag}
                </span>
              ))}
            </div>
          </header>

          <div className="blog-post-image" style={{
            marginBottom: '60px',
            borderRadius: '20px',
            overflow: 'hidden',
            boxShadow: '0 20px 60px rgba(0, 0, 0, 0.3)'
          }}>
            <img src={post.featured_image} alt={post.title} style={{
              width: '100%',
              height: 'auto',
              display: 'block',
              transition: 'transform 0.3s ease'
            }} />
          </div>

          <div className="blog-post-body" style={{
            fontSize: '1.1rem',
            lineHeight: '1.8',
            color: 'var(--text-primary)',
            maxWidth: '100%'
          }}>
            <div
              dangerouslySetInnerHTML={{ __html: post.content }}
              style={{
                '& h2': {
                  fontSize: '2rem',
                  fontWeight: '600',
                  marginTop: '50px',
                  marginBottom: '25px',
                  color: 'var(--accent-green)'
                },
                '& h3': {
                  fontSize: '1.5rem',
                  fontWeight: '600',
                  marginTop: '40px',
                  marginBottom: '20px'
                },
                '& p': {
                  marginBottom: '25px',
                  lineHeight: '1.8'
                },
                '& img': {
                  width: '100%',
                  height: 'auto',
                  borderRadius: '12px',
                  margin: '30px 0',
                  boxShadow: '0 10px 30px rgba(0, 0, 0, 0.2)'
                },
                '& code': {
                  background: 'rgba(255, 255, 255, 0.1)',
                  padding: '2px 8px',
                  borderRadius: '4px',
                  fontSize: '0.9em',
                  color: 'var(--accent-green)'
                },
                '& pre': {
                  background: 'rgba(0, 0, 0, 0.3)',
                  padding: '25px',
                  borderRadius: '12px',
                  overflow: 'auto',
                  margin: '30px 0',
                  border: '1px solid rgba(255, 255, 255, 0.1)'
                },
                '& blockquote': {
                  borderLeft: '4px solid var(--accent-green)',
                  paddingLeft: '25px',
                  margin: '30px 0',
                  fontStyle: 'italic',
                  color: 'var(--text-secondary)',
                  fontSize: '1.1em'
                },
                '& ul, & ol': {
                  paddingLeft: '30px',
                  marginBottom: '25px'
                },
                '& li': {
                  marginBottom: '10px',
                  lineHeight: '1.6'
                }
              }}
            />
          </div>

          <div style={{
            marginTop: '80px',
            padding: '40px',
            background: 'rgba(0, 212, 170, 0.05)',
            borderRadius: '20px',
            border: '1px solid rgba(0, 212, 170, 0.1)',
            textAlign: 'center'
          }}>
            <h3 style={{
              marginBottom: '20px',
              color: 'var(--accent-green)',
              fontSize: '1.5rem'
            }}>
              Enjoyed this article?
            </h3>
            <p style={{
              marginBottom: '30px',
              color: 'var(--text-secondary)',
              fontSize: '1.1rem'
            }}>
              Check out more of our insights and tutorials
            </p>
            <Link
              to="/blog"
              className="cta-button"
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: '10px'
              }}
            >
              View More Articles
              <i className="fas fa-arrow-right"></i>
            </Link>
          </div>
        </article>
      </div>
    </div>
  );
};

export default BlogPost;

src/pages/Projects.js.content:
import React, { useEffect, useState } from 'react';
import CardSwap, { Card } from '../components/CardSwap';
import Model3D from '../components/Model3D';
import { WavyBackground } from '../components/WavyBackground';
import { projects } from '../data/mockData';
import SEOHead from '../components/SEOHead';

const Projects = () => {
  const [filter, setFilter] = useState('all');
  const [filteredProjects, setFilteredProjects] = useState(projects);

  const projectsStructuredData = {
    "@context": "https://schema.org",
    "@type": "WebPage",
    "name": "Our Projects | Luphonix Digital Innovation Portfolio",
    "description": "Explore our portfolio of innovative digital solutions, web applications, mobile apps, AI/ML projects, and 3D visualization work.",
    "url": "https://luphonix.com/projects"
  };

  useEffect(() => {
    if (filter === 'all') {
      setFilteredProjects(projects);
    } else {
      setFilteredProjects(projects.filter(project => 
        project.category?.toLowerCase() === filter.toLowerCase() ||
        project.technologies.some(tech => tech.toLowerCase().includes(filter.toLowerCase()))
      ));
    }
  }, [filter]);

  useEffect(() => {
    // Add fade-in animation on scroll
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('animated');
        }
      });
    });

    document.querySelectorAll('.fade-in').forEach(el => observer.observe(el));

    return () => observer.disconnect();
  }, [filteredProjects]);

  const categories = ['all', 'web development', 'mobile app', 'ai/ml', 'blockchain', 'e-commerce'];

  return (
    <>
      <SEOHead
        title="Projects | Luphonix Digital Innovation Portfolio | Web Apps & AI Solutions"
        description="Explore our portfolio of innovative digital solutions including web applications, mobile apps, AI/ML projects, blockchain solutions, e-commerce platforms, and 3D visualization work."
        keywords="digital projects, web application portfolio, mobile app projects, AI projects, machine learning portfolio, blockchain projects, e-commerce development, 3D visualization projects, software development portfolio"
        canonical="https://luphonix.com/projects"
        structuredData={projectsStructuredData}
      />
      <div className="projects-page">
      {/* Header Section */}
      <section className="section" style={{ position: 'relative', height: '60vh', overflow: 'hidden' }}>
        <div style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%' }}>
          <WavyBackground
            containerClassName=""
            style={{ width: '100%', height: '100%' }}
            waveWidth={30}
            backgroundFill="#0a0a0a"
            blur={10}
            speed="fast"
            waveOpacity={0.4}
          />
        </div>
        <div className="container" style={{ position: 'relative', zIndex: 2, display: 'flex', alignItems: 'center', height: '100%' }}>
          <div style={{ textAlign: 'center', width: '100%' }}>
            <h1 className="section-title fade-in" style={{ color: 'white', textShadow: '2px 2px 4px rgba(0,0,0,0.8)' }}>Our Projects</h1>
            <p className="section-subtitle fade-in" style={{ color: 'rgba(255,255,255,0.9)', textShadow: '1px 1px 2px rgba(0,0,0,0.8)' }}>
              Showcasing our portfolio of innovative solutions and successful client collaborations
            </p>
          </div>
        </div>
      </section>

      {/* Filter Section */}
      <section className="section" style={{ paddingTop: 0, paddingBottom: '80px' }}>
        <div className="container">
          <div className="filter-buttons" style={{ 
            display: 'flex', 
            justifyContent: 'center', 
            flexWrap: 'wrap',
            gap: '15px',
            marginBottom: '60px'
          }}>
            {categories.map(category => (
              <button
                key={category}
                onClick={() => setFilter(category)}
                className={filter === category ? 'filter-btn active' : 'filter-btn'}
                style={{
                  padding: '12px 24px',
                  background: filter === category ? 'var(--accent-green)' : 'transparent',
                  color: filter === category ? 'var(--primary-bg)' : 'var(--text-secondary)',
                  border: `1px solid ${filter === category ? 'var(--accent-green)' : 'var(--border-color)'}`,
                  borderRadius: '25px',
                  cursor: 'pointer',
                  transition: 'var(--transition-fast)',
                  fontSize: '14px',
                  textTransform: 'capitalize',
                  fontWeight: '300'
                }}
              >
                {category}
              </button>
            ))}
          </div>

          {/* Projects Grid */}
          <div className="projects-grid">
            {filteredProjects.map((project, index) => (
              <div key={project.id} className="project-card fade-in" style={{ animationDelay: `${index * 0.1}s` }}>
                <img src={project.image} alt={project.title} className="project-image" />
                <div className="project-content">
                  <h3 className="project-title">{project.title}</h3>
                  <p className="project-description">{project.short_description}</p>
                  <div className="project-tech">
                    {project.technologies.slice(0, 5).map(tech => (
                      <span key={tech} className="tech-tag">{tech}</span>
                    ))}
                  </div>
                  <div style={{ display: 'flex', gap: '15px', marginTop: '25px' }}>
                    {project.project_url && (
                      <a 
                        href={project.project_url} 
                        target="_blank" 
                        rel="noopener noreferrer" 
                        className="cta-button" 
                        style={{ fontSize: '12px', padding: '10px 20px' }}
                      >
                        <i className="fas fa-external-link-alt" style={{ marginRight: '8px' }}></i>
                        View Live
                      </a>
                    )}
                    {project.github_url && (
                      <a 
                        href={project.github_url} 
                        target="_blank" 
                        rel="noopener noreferrer" 
                        className="cta-button" 
                        style={{ 
                          fontSize: '12px', 
                          padding: '10px 20px', 
                          background: 'transparent', 
                          border: '1px solid var(--accent-green)',
                          color: 'var(--accent-green)'
                        }}
                      >
                        <i className="fab fa-github" style={{ marginRight: '8px' }}></i>
                        GitHub
                      </a>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>

          {filteredProjects.length === 0 && (
            <div style={{ textAlign: 'center', padding: '60px 0' }}>
              <h3 style={{ color: 'var(--text-secondary)', marginBottom: '20px' }}>No projects found</h3>
              <p style={{ color: 'var(--text-muted)' }}>Try selecting a different category filter</p>
            </div>
          )}
        </div>
      </section>

      {/* 3D Model Experience Section */}
      <section className="section" style={{ backgroundColor: 'var(--secondary-bg)', padding: '120px 0' }}>
        <div className="container">
          <h2 className="section-title fade-in">3D Project Showcase</h2>
          <p className="section-subtitle fade-in" style={{ marginBottom: '60px' }}>
            Explore our project portfolio through interactive 3D visualization
          </p>
          <div className="fade-in" style={{ 
            animationDelay: '0.2s',
            maxWidth: '800px',
            margin: '0 auto'
          }}>
            <Model3D 
              modelPath="/krishna.glb"
              containerStyle={{
                height: '500px'
              }}
              showBorder={false}
              enableRotation={false}
            />
            <p style={{ 
              color: 'var(--text-secondary)', 
              textAlign: 'center',
              fontSize: '14px',
              fontWeight: '300',
              marginTop: '20px'
            }}>
              Interactive 3D showcase demonstrating our project development and visualization skills
            </p>
          </div>
        </div>
      </section>

      <div style={{ 
        height: '600px', 
        position: 'relative', 
        margin: '80px 0', 
        background: 'linear-gradient(135deg, rgba(10, 10, 10, 0.1), rgba(26, 26, 26, 0.05))',
        borderRadius: '20px',
        overflow: 'hidden'
      }}>
        <CardSwap
          cardDistance={60}
          verticalDistance={70}
          delay={5000}
          pauseOnHover={true}
        >
          <Card>
            <div style={{ 
              height: '100%',
              background: 'linear-gradient(135deg, rgba(0, 212, 170, 0.1), rgba(138, 43, 226, 0.1))',
              backdropFilter: 'blur(20px)',
              border: '1px solid rgba(0, 212, 170, 0.3)',
              borderRadius: '12px',
