src/src/components/BlogAnimations.css.content:
/* Blog Animation Styles */
.blog-card-animated {
  position: relative;
  overflow: hidden;
  transform: translateY(0);
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  background: linear-gradient(135deg, 
    rgba(255, 255, 255, 0.05) 0%, 
    rgba(255, 255, 255, 0.02) 100%);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.blog-card-animated::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, 
    transparent, 
    rgba(0, 212, 170, 0.1), 
    transparent);
  transition: left 0.6s ease;
  z-index: 1;
}

.blog-card-animated:hover::before {
  left: 100%;
}

.blog-card-animated:hover {
  transform: translateY(-10px) rotateX(2deg);
  box-shadow: 
    0 20px 40px rgba(0, 0, 0, 0.2),
    0 0 30px rgba(0, 212, 170, 0.1);
  border-color: rgba(0, 212, 170, 0.3);
}

.blog-image-container {
  position: relative;
  overflow: hidden;
  border-radius: 12px 12px 0 0;
}

.blog-image-animated {
  transition: all 0.6s cubic-bezier(0.4, 0, 0.2, 1);
  transform: scale(1);
}

.blog-card-animated:hover .blog-image-animated {
  transform: scale(1.05);
}

.blog-content-animated {
  position: relative;
  z-index: 2;
  padding: 30px;
}

.blog-title-animated {
  transition: all 0.3s ease;
  background: linear-gradient(135deg, var(--text-primary), var(--accent-green));
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-size: 200% 200%;
  animation: titleGradient 3s ease infinite;
}

@keyframes titleGradient {
  0%, 100% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
}

.blog-card-animated:hover .blog-title-animated {
  transform: translateX(5px);
}

.tech-tag-animated {
  position: relative;
  overflow: hidden;
  transition: all 0.3s ease;
  background: rgba(0, 212, 170, 0.1);
  border: 1px solid rgba(0, 212, 170, 0.3);
}

.tech-tag-animated::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, 
    transparent, 
    rgba(0, 212, 170, 0.3), 
    transparent);
  transition: left 0.5s ease;
}

.tech-tag-animated:hover::before {
  left: 100%;
}

.tech-tag-animated:hover {
  transform: scale(1.05);
  background: rgba(0, 212, 170, 0.2);
  border-color: var(--accent-green);
}

.blog-meta-animated {
  transition: all 0.3s ease;
}

.blog-card-animated:hover .blog-meta-animated {
  transform: translateY(-5px);
  color: var(--accent-green);
}

.cta-button-animated {
  position: relative;
  overflow: hidden;
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.cta-button-animated::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  background: radial-gradient(circle, rgba(0, 212, 170, 0.3) 0%, transparent 70%);
  transition: all 0.4s ease;
  transform: translate(-50%, -50%);
  border-radius: 50%;
}

.cta-button-animated:hover::before {
  width: 300px;
  height: 300px;
}

.floating-particles {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  pointer-events: none;
  overflow: hidden;
}

.particle {
  position: absolute;
  width: 4px;
  height: 4px;
  background: rgba(0, 212, 170, 0.3);
  border-radius: 50%;
  animation: float 6s infinite linear;
}

@keyframes float {
  0% {
    transform: translateY(100vh) rotate(0deg);
    opacity: 0;
  }
  10% {
    opacity: 1;
  }
  90% {
    opacity: 1;
  }
  100% {
    transform: translateY(-100px) rotate(360deg);
    opacity: 0;
  }
}

.particle:nth-child(1) { left: 20%; animation-delay: 0s; }
.particle:nth-child(2) { left: 40%; animation-delay: 1s; }
.particle:nth-child(3) { left: 60%; animation-delay: 2s; }
.particle:nth-child(4) { left: 80%; animation-delay: 3s; }
.particle:nth-child(5) { left: 10%; animation-delay: 4s; }

.blog-grid-animated {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
  gap: 40px;
  perspective: 1000px;
}

/* Staggered animation for blog cards */
.blog-card-animated.fade-in {
  opacity: 0;
  transform: translateY(60px) rotateX(10deg);
  animation: blogCardSlideIn 0.8s cubic-bezier(0.4, 0, 0.2, 1) forwards;
}

@keyframes blogCardSlideIn {
  to {
    opacity: 1;
    transform: translateY(0) rotateX(0);
  }
}

/* Reading progress indicator */
.reading-progress {
  position: absolute;
  bottom: 0;
  left: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--accent-green), rgba(0, 212, 170, 0.5));
  transition: width 0.3s ease;
  width: 0;
}

.blog-card-animated:hover .reading-progress {
  width: 100%;
}

/* Pulsing effect for new posts */
.blog-card-new {
  animation: pulseGlow 2s infinite;
}

@keyframes pulseGlow {
  0%, 100% {
    box-shadow: 0 0 20px rgba(0, 212, 170, 0.2);
  }
  50% {
    box-shadow: 0 0 30px rgba(0, 212, 170, 0.4);
  }
}

/* Mobile responsive animations */
@media (max-width: 768px) {
  .blog-card-animated:hover {
    transform: translateY(-5px);
  }

  .blog-grid-animated {
    grid-template-columns: 1fr;
    gap: 30px;
  }
}

