import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useBlog } from '../context/BlogContext';

const BlogAdmin = () => {
  const { state, dispatch } = useBlog();
  const { posts } = state;
  const [searchTerm, setSearchTerm] = useState('');
  const [filteredPosts, setFilteredPosts] = useState(posts);

  useEffect(() => {
    const filtered = posts.filter(post =>
      post.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      post.excerpt.toLowerCase().includes(searchTerm.toLowerCase())
    );
    setFilteredPosts(filtered);
  }, [searchTerm, posts]);

  const handleDelete = (postId) => {
    if (window.confirm('Are you sure you want to delete this post?')) {
      dispatch({ type: 'DELETE_POST', payload: postId });
    }
  };

  return (
    <div className="admin-page">
      <section className="section">
        <div className="container">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '40px' }}>
            <h1 className="section-title" style={{ textAlign: 'left', marginBottom: 0 }}>Blog Administration</h1>
            <Link 
              to="/blog/create" 
              className="cta-button"
              style={{ display: 'inline-flex', alignItems: 'center' }}
            >
              <i className="fas fa-plus" style={{ marginRight: '8px' }}></i>
              Create New Post
            </Link>
          </div>

          {/* Search Bar */}
          <div style={{ marginBottom: '40px' }}>
            <input
              type="text"
              placeholder="Search posts..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              style={{
                width: '100%',
                maxWidth: '400px',
                padding: '12px 20px',
                background: 'rgba(255, 255, 255, 0.05)',
                border: '1px solid var(--border-color)',
                borderRadius: '25px',
                color: 'var(--text-primary)',
                fontSize: '14px',
                outline: 'none'
              }}
            />
          </div>

          {/* Posts Table */}
          <div style={{ 
            background: 'rgba(255, 255, 255, 0.02)',
            border: '1px solid var(--border-color)',
            borderRadius: '16px',
            overflow: 'hidden'
          }}>
            <div style={{
              display: 'grid',
              gridTemplateColumns: '60px 1fr 150px 120px 100px 120px',
              padding: '20px',
              background: 'rgba(0, 212, 170, 0.1)',
              borderBottom: '1px solid var(--border-color)',
              fontSize: '12px',
              fontWeight: '500',
              textTransform: 'uppercase',
              letterSpacing: '0.1em',
              color: 'var(--text-secondary)'
            }}>
              <span>ID</span>
              <span>Title</span>
              <span>Author</span>
              <span>Date</span>
              <span>Read Time</span>
              <span>Actions</span>
            </div>

            {filteredPosts.map(post => (
              <div 
                key={post.id}
                style={{
                  display: 'grid',
                  gridTemplateColumns: '60px 1fr 150px 120px 100px 120px',
                  padding: '20px',
                  borderBottom: '1px solid rgba(255, 255, 255, 0.05)',
                  alignItems: 'center',
                  transition: 'var(--transition-fast)'
                }}
                onMouseEnter={(e) => e.target.style.background = 'rgba(255, 255, 255, 0.02)'}
                onMouseLeave={(e) => e.target.style.background = 'transparent'}
              >
                <span style={{ color: 'var(--text-muted)', fontSize: '12px' }}>#{post.id}</span>
                <div>
                  <Link 
                    to={`/blog/${post.slug}`}
                    style={{ 
                      color: 'var(--text-primary)', 
                      textDecoration: 'none',
                      fontWeight: '300'
                    }}
                  >
                    {post.title}
                  </Link>
                  <div style={{ 
                    color: 'var(--text-muted)', 
                    fontSize: '12px', 
                    marginTop: '4px',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap'
                  }}>
                    {post.excerpt.substring(0, 50)}...
                  </div>
                </div>
                <span style={{ color: 'var(--text-secondary)', fontSize: '12px' }}>
                  {post.author || 'Luphonix Team'}
                </span>
                <span style={{ color: 'var(--text-secondary)', fontSize: '12px' }}>
                  {new Date(post.created_at).toLocaleDateString()}
                </span>
                <span style={{ color: 'var(--text-secondary)', fontSize: '12px' }}>
                  {post.read_time} min
                </span>
                <div style={{ display: 'flex', gap: '8px' }}>
                  <Link
                    to={`/blog/edit/${post.id}`}
                    style={{
                      padding: '6px 12px',
                      background: 'rgba(0, 212, 170, 0.1)',
                      color: 'var(--accent-green)',
                      textDecoration: 'none',
                      borderRadius: '6px',
                      fontSize: '11px',
                      border: '1px solid rgba(0, 212, 170, 0.2)',
                      transition: 'var(--transition-fast)'
                    }}
                  >
                    Edit
                  </Link>
                  <button
                    onClick={() => handleDelete(post.id)}
                    style={{
                      padding: '6px 12px',
                      background: 'rgba(255, 59, 48, 0.1)',
                      color: '#ff3b30',
                      border: '1px solid rgba(255, 59, 48, 0.2)',
                      borderRadius: '6px',
                      fontSize: '11px',
                      cursor: 'pointer',
                      transition: 'var(--transition-fast)'
                    }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            ))}
          </div>

          {filteredPosts.length === 0 && (
            <div style={{ textAlign: 'center', padding: '60px 0' }}>
              <h3 style={{ color: 'var(--text-secondary)', marginBottom: '20px' }}>No posts found</h3>
              <p style={{ color: 'var(--text-muted)' }}>
                {searchTerm ? 'Try adjusting your search terms' : 'Create your first blog post'}
              </p>
            </div>
          )}
        </div>
      </section>
    </div>
  );
};

export default BlogAdmin;

src/src/pages/BlogCreate.js.content:
import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useBlog } from '../context/BlogContext';

const BlogCreate = () => {
  const navigate = useNavigate();
  const { dispatch } = useBlog();
  const [formData, setFormData] = useState({
    title: '',
    excerpt: '',
    content: '',
    featured_image: '',
    tags: '',
    author: '',
    read_time: 5
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const generateSlug = (title) => {
    return title
      .toLowerCase()
      .replace(/[^\w\s-]/g, '')
      .replace(/\s+/g, '-')
      .replace(/-+/g, '-')
      .trim();
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      const newPost = {
        id: Date.now(),
        ...formData,
        slug: generateSlug(formData.title),
        tags: formData.tags.split(',').map(tag => tag.trim()).filter(tag => tag),
        author: formData.author || 'Luphonix Team',
        created_at: new Date().toISOString(),
        read_time: parseInt(formData.read_time) || 5,
        featured_image: formData.featured_image || 'https://images.unsplash.com/photo-1486312338219-ce68d2c6f44d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80'
      };

      dispatch({ type: 'ADD_POST', payload: newPost });
      navigate('/blog/admin');
    } catch (error) {
      console.error('Error creating post:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="create-post-page">
      <section className="section">
        <div className="container" style={{ maxWidth: '800px' }}>
          <div style={{ marginBottom: '40px' }}>
            <Link 
              to="/blog/admin" 
              style={{ 
                color: 'var(--accent-green)', 
                textDecoration: 'none',
                display: 'inline-flex',
                alignItems: 'center',
                marginBottom: '30px',
                fontSize: '14px'
              }}
            >
              <i className="fas fa-arrow-left" style={{ marginRight: '10px' }}></i>
              Back to Admin
            </Link>

            <h1 className="section-title" style={{ textAlign: 'left', marginBottom: '10px' }}>
              Create New Blog Post
            </h1>
            <p style={{ color: 'var(--text-secondary)' }}>
              Fill in the details below to create a new blog post
            </p>
          </div>

          <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '30px' }}>
            {/* Title */}
            <div>
              <label style={{ 
                display: 'block', 
                marginBottom: '8px', 
                color: 'var(--text-primary)',
                fontSize: '14px',
                fontWeight: '300'
              }}>
                Post Title *
              </label>
              <input
                type="text"
                name="title"
                value={formData.title}
                onChange={handleChange}
                required
                placeholder="Enter the blog post title"
                style={{
                  width: '100%',
                  padding: '16px 20px',
                  background: 'rgba(255, 255, 255, 0.05)',
                  border: '1px solid var(--border-color)',
                  borderRadius: '12px',
                  color: 'var(--text-primary)',
                  fontSize: '16px',
                  outline: 'none',
                  transition: 'var(--transition-fast)'
                }}
              />
            </div>

            {/* Excerpt */}
            <div>
              <label style={{ 
                display: 'block', 
                marginBottom: '8px', 
                color: 'var(--text-primary)',
                fontSize: '14px',
                fontWeight: '300'
              }}>
                Excerpt *
              </label>
              <textarea
                name="excerpt"
                value={formData.excerpt}
                onChange={handleChange}
                required
                placeholder="Brief description of the post"
                rows={3}
                style={{
                  width: '100%',
                  padding: '16px 20px',
                  background: 'rgba(255, 255, 255, 0.05)',
                  border: '1px solid var(--border-color)',
                  borderRadius: '12px',
                  color: 'var(--text-primary)',
                  fontSize: '16px',
                  outline: 'none',
                  resize: 'vertical',
                  minHeight: '80px',
                  transition: 'var(--transition-fast)'
                }}
              />
            </div>

            {/* Content */}
            <div>
              <label style={{ 
                display: 'block', 
                marginBottom: '8px', 
                color: 'var(--text-primary)',
                fontSize: '14px',
                fontWeight: '300'
              }}>
                Content *
              </label>
              <textarea
                name="content"
                value={formData.content}
                onChange={handleChange}
                required
                placeholder="Write your blog post content here..."
                rows={12}
                style={{
                  width: '100%',
                  padding: '20px',
                  background: 'rgba(255, 255, 255, 0.05)',
                  border: '1px solid var(--border-color)',
                  borderRadius: '12px',
                  color: 'var(--text-primary)',
                  fontSize: '16px',
                  outline: 'none',
                  resize: 'vertical',
                  minHeight: '300px',
                  lineHeight: '1.6',
                  transition: 'var(--transition-fast)'
                }}
              />
            </div>

            {/* Row for Featured Image and Author */}
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
              <div>
                <label style={{ 
                  display: 'block', 
                  marginBottom: '8px', 
                  color: 'var(--text-primary)',
                  fontSize: '14px',
                  fontWeight: '300'
                }}>
                  Featured Image URL
                </label>
                <input
                  type="url"
                  name="featured_image"
                  value={formData.featured_image}
                  onChange={handleChange}
                  placeholder="https://example.com/image.jpg"
                  style={{
                    width: '100%',
                    padding: '16px 20px',
                    background: 'rgba(255, 255, 255, 0.05)',
                    border: '1px solid var(--border-color)',
                    borderRadius: '12px',
                    color: 'var(--text-primary)',
                    fontSize: '16px',
                    outline: 'none',
                    transition: 'var(--transition-fast)'
                  }}
                />
              </div>

              <div>
                <label style={{ 
                  display: 'block', 
                  marginBottom: '8px', 
                  color: 'var(--text-primary)',
                  fontSize: '14px',
                  fontWeight: '300'
                }}>
                  Author
                </label>
                <input
                  type="text"
                  name="author"
                  value={formData.author}
                  onChange={handleChange}
                  placeholder="Author name (optional)"
                  style={{
                    width: '100%',
                    padding: '16px 20px',
                    background: 'rgba(255, 255, 255, 0.05)',
                    border: '1px solid var(--border-color)',
                    borderRadius: '12px',
                    color: 'var(--text-primary)',
                    fontSize: '16px',
                    outline: 'none',
                    transition: 'var(--transition-fast)'
                  }}
                />
              </div>
            </div>

            {/* Row for Tags and Read Time */}
            <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '20px' }}>
              <div>
                <label style={{ 
                  display: 'block', 
                  marginBottom: '8px', 
                  color: 'var(--text-primary)',
                  fontSize: '14px',
                  fontWeight: '300'
                }}>
                  Tags (comma-separated)
                </label>
                <input
                  type="text"
                  name="tags"
                  value={formData.tags}
                  onChange={handleChange}
                  placeholder="React, JavaScript, Web Development"
                  style={{
                    width: '100%',
                    padding: '16px 20px',
                    background: 'rgba(255, 255, 255, 0.05)',
                    border: '1px solid var(--border-color)',
                    borderRadius: '12px',
                    color: 'var(--text-primary)',
                    fontSize: '16px',
                    outline: 'none',
                    transition: 'var(--transition-fast)'
                  }}
                />
              </div>

              <div>
                <label style={{ 
                  display: 'block', 
                  marginBottom: '8px', 
                  color: 'var(--text-primary)',
                  fontSize: '14px',
                  fontWeight: '300'
                }}>
                  Read Time (minutes)
                </label>
                <input
                  type="number"
                  name="read_time"
                  value={formData.read_time}
                  onChange={handleChange}
                  min="1"
                  max="60"
                  style={{
                    width: '100%',
                    padding: '16px 20px',
                    background: 'rgba(255, 255, 255, 0.05)',
                    border: '1px solid var(--border-color)',
                    borderRadius: '12px',
                    color: 'var(--text-primary)',
                    fontSize: '16px',
                    outline: 'none',
                    transition: 'var(--transition-fast)'
                  }}
                />
              </div>
            </div>

            {/* Submit Button */}
            <div style={{ display: 'flex', gap: '15px', justifyContent: 'flex-end', paddingTop: '20px' }}>
              <Link 
                to="/blog/admin"
                style={{
                  padding: '16px 30px',
                  background: 'transparent',
                  color: 'var(--text-secondary)',
                  border: '1px solid var(--border-color)',
                  borderRadius: '12px',
                  textDecoration: 'none',
                  fontSize: '16px',
                  transition: 'var(--transition-fast)',
                  display: 'inline-flex',
                  alignItems: 'center'
                }}
              >
                Cancel
              </Link>
              <button
                type="submit"
                disabled={isSubmitting}
                className="cta-button"
                style={{
                  padding: '16px 30px',
                  fontSize: '16px',
                  opacity: isSubmitting ? 0.7 : 1,
                  cursor: isSubmitting ? 'not-allowed' : 'pointer'
                }}
              >
                {isSubmitting ? 'Creating...' : 'Create Post'}
                {!isSubmitting && <i className="fas fa-plus" style={{ marginLeft: '10px' }}></i>}
              </button>
            </div>
          </form>
        </div>
      </section>
    </div>
  );
};

export default BlogCreate;

src/src/pages/BlogEdit.js.content:
import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link, Navigate } from 'react-router-dom';
import { useBlog } from '../context/BlogContext';

const BlogEdit = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { state, dispatch } = useBlog();
  const { posts } = state;

  const post = posts.find(p => p.id === parseInt(id));
  const [formData, setFormData] = useState({
    title: '',
    excerpt: '',
    content: '',
    featured_image: '',
    tags: '',
    author: '',
    read_time: 5
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    if (post) {
      setFormData({
        title: post.title,
        excerpt: post.excerpt,
        content: post.content || '',
        featured_image: post.featured_image,
        tags: post.tags.join(', '),
        author: post.author || '',
        read_time: post.read_time
      });
    }
  }, [post]);

  if (!post) {
    return <Navigate to="/blog/admin" replace />;
  }

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const generateSlug = (title) => {
    return title
      .toLowerCase()
      .replace(/[^\w\s-]/g, '')
      .replace(/\s+/g, '-')
      .replace(/-+/g, '-')
      .trim();
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      const updatedPost = {
        ...post,
        ...formData,
        slug: generateSlug(formData.title),
        tags: formData.tags.split(',').map(tag => tag.trim()).filter(tag => tag),
        read_time: parseInt(formData.read_time) || 5,
        updated_at: new Date().toISOString()
      };

      dispatch({ type: 'UPDATE_POST', payload: updatedPost });
      navigate('/blog/admin');
    } catch (error) {
      console.error('Error updating post:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="edit-post-page">
      <section className="section">
        <div className="container" style={{ maxWidth: '800px' }}>
          <div style={{ marginBottom: '40px' }}>
            <Link 
              to="/blog/admin" 
              style={{ 
                color: 'var(--accent-green)', 
                textDecoration: 'none',
                display: 'inline-flex',
                alignItems: 'center',
                marginBottom: '30px',
                fontSize: '14px'
              }}
            >
              <i className="fas fa-arrow-left" style={{ marginRight: '10px' }}></i>
              Back to Admin
            </Link>

            <h1 className="section-title" style={{ textAlign: 'left', marginBottom: '10px' }}>
              Edit Blog Post
            </h1>
            <p style={{ color: 'var(--text-secondary)' }}>
              Update the details of your blog post
            </p>
          </div>

          <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '30px' }}>
            {/* Title */}
            <div>
              <label style={{ 
                display: 'block', 
                marginBottom: '8px', 
                color: 'var(--text-primary)',
                fontSize: '14px',
                fontWeight: '300'
              }}>
                Post Title *
              </label>
              <input
                type="text"
                name="title"
                value={formData.title}
                onChange={handleChange}
                required
                placeholder="Enter the blog post title"
                style={{
                  width: '100%',
                  padding: '16px 20px',
                  background: 'rgba(255, 255, 255, 0.05)',
                  border: '1px solid var(--border-color)',
