                onChange={handleChange}
                required
                placeholder="Brief description of the post"
                rows={3}
                style={{
                  width: '100%',
                  padding: '16px 20px',
                  background: 'rgba(255, 255, 255, 0.05)',
                  border: '1px solid var(--border-color)',
                  borderRadius: '12px',
