                  outline: 'none',
                  resize: 'vertical',
                  minHeight: '300px',
                  lineHeight: '1.6',
                  transition: 'var(--transition-fast)'
                }}
              />
            </div>

            {/* Row for Featured Image and Author */}
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
              <div>
                <label style={{ 
                  display: 'block', 
                  marginBottom: '8px', 
                  color: 'var(--text-primary)',
                  fontSize: '14px',
                  fontWeight: '300'
                }}>
                  Featured Image URL
                </label>
                <input
                  type="url"
