                    width: '100%',
                    padding: '16px 20px',
                    background: 'rgba(255, 255, 255, 0.05)',
                    border: '1px solid var(--border-color)',
                    borderRadius: '12px',
                    color: 'var(--text-primary)',
                    fontSize: '16px',
                    outline: 'none',
                    transition: 'var(--transition-fast)'
                  }}
                />
              </div>

              <div>
                <label style={{ 
                  display: 'block', 
                  marginBottom: '8px', 
                  color: 'var(--text-primary)',
                  fontSize: '14px',
                  fontWeight: '300'
                }}>
                  Read Time (minutes)
                </label>
                <input
                  type="number"
                  name="read_time"
                  value={formData.read_time}
                  onChange={handleChange}
                  min="1"
                  max="60"
                  style={{
                    width: '100%',
                    padding: '16px 20px',
                    background: 'rgba(255, 255, 255, 0.05)',
                    border: '1px solid var(--border-color)',
                    borderRadius: '12px',
                    color: 'var(--text-primary)',
                    fontSize: '16px',
                    outline: 'none',
                    transition: 'var(--transition-fast)'
                  }}
                />
              </div>
            </div>

            {/* Submit Buttons */}
            <div style={{ display: 'flex', gap: '15px', justifyContent: 'flex-end', paddingTop: '20px' }}>
              <Link 
                to="/blog/admin"
                style={{
                  padding: '16px 30px',
                  background: 'transparent',
                  color: 'var(--text-secondary)',
                  border: '1px solid var(--border-color)',
                  borderRadius: '12px',
                  textDecoration: 'none',
                  fontSize: '16px',
                  transition: 'var(--transition-fast)',
                  display: 'inline-flex',
                  alignItems: 'center'
                }}
              >
                Cancel
              </Link>
              <button
                type="submit"
                disabled={isSubmitting}
                className="cta-button"
                style={{
                  padding: '16px 30px',
                  fontSize: '16px',
                  opacity: isSubmitting ? 0.7 : 1,
                  cursor: isSubmitting ? 'not-allowed' : 'pointer'
                }}
              >
                {isSubmitting ? 'Updating...' : 'Update Post'}
                {!isSubmitting && <i className="fas fa-save" style={{ marginLeft: '10px' }}></i>}
              </button>
            </div>
          </form>
        </div>
      </section>
    </div>
  );
};

export default BlogEdit;

